mapper.select:
SELECT ob.card_id, ot.card_desc, ob.card_money, ot.card_start_time, oyt.card_num, ot.card_name, ob.user_id, ob.card_code, ob.card_fetch_time, ob.card_media_id, ob.server_id, ob.user_account, ob.card_time, ob.card_froze_money, ob.card_password FROM ${database.prefix.payment}hou_pay_card_base ot LEFT JOIN ${database.prefix.payment}hou_pay_card_info ob ON ot.card_id = ob.card_id LEFT JOIN ( SELECT card_id, count(*) card_num FROM ${database.prefix.payment}hou_pay_card_info GROUP BY card_id ) oyt ON oyt.card_id = ob.card_id WHERE 1 =1
AND ot.card_id = #{param.cardId}
AND ob.card_code = #{param.cardCode}
AND ob.user_account =''
AND ot.card_start_time between #{param.returnAddTimeStart} and #{param.returnAddTimeEnd}

SELECT b.order_id, r.record_status, r.trade_type_id, r.record_money, r.record_time, r.record_payorder, b.pay_code, t.trade_payment_recharge_card, r.user_id, r.user_nickname, record_title, record_desc, trade_third_party_amount, b.order_is_shop_take, b.virtual_goods, b.past_due, b.is_cancel, b.order_refund_status, b.order_return_status, b.order_payment_amount, b.order_status FROM ${database.prefix.order}hou_order_base b LEFT JOIN ${database.prefix.payment}hou_pay_consume_record r FORCE INDEX ( `record_time` ) ON r.record_payorder = b.order_id LEFT JOIN ${database.prefix.payment}hou_pay_consume_trade t ON t.order_id = b.order_id LEFT JOIN ${database.prefix.supplier}hou_shop_base sb ON sb.supplier_shop_id = b.shop_id WHERE b.pay_code in (6,7,8)
and r.trade_type_id = #{param.tradeTypeId,jdbcType=TINYINT} and r.user_type = 2
and r.trade_type_id =#{param.tradeTypeId,jdbcType=TINYINT} and r.user_type = 1 and (b.order_return_status = 2 OR b.order_refund_status = 2)
and r.user_id = #{param.userId,jdbcType=INTEGER}
and r.user_nickname = #{param.userNickname}
and r.record_payorder = #{param.orderId,jdbcType=VARCHAR}
and (r.record_time BETWEEN #{param.startDate} and #{param.endDate})
order by record_time desc limit 6000

SELECT b.order_id, b.order_status, r.record_status, r.trade_type_id, r.record_money, r.record_time as recordTime, r.record_payorder, b.pay_code, t.trade_payment_recharge_card, r.user_id, r.user_nickname, r.record_title, r.record_desc, t.trade_third_party_amount FROM ${database.prefix.order}hou_order_base b LEFT JOIN ${database.prefix.payment}hou_pay_consume_record r ON r.record_payorder = b.order_id LEFT JOIN ${database.prefix.payment}hou_pay_consume_trade t ON t.order_id = b.order_id LEFT JOIN ${database.prefix.supplier}hou_shop_base sb ON sb.supplier_shop_id = b.shop_id WHERE b.pay_code in (6,7,8)
and r.user_type = 2
and r.trade_type_id = #{param.tradeTypeId} and r.user_type = 2
and r.trade_type_id = #{param.tradeTypeId} and r.user_type = 1 and (b.order_return_status = 2 OR b.order_refund_status = 2)
and r.user_id = #{param.userId}
and r.user_nickname = #{param.userNickname}
and r.record_payorder = #{param.orderId,jdbcType=VARCHAR}
and (r.record_time BETWEEN #{param.startDate} and #{param.endDate})
group by b.order_id order by record_time desc

SELECT IFNULL(sum(r.record_money),0) FROM ${database.prefix.order}hou_order_base b LEFT JOIN ${database.prefix.payment}hou_pay_consume_record r ON r.record_payorder = b.order_id LEFT JOIN ${database.prefix.payment}hou_pay_consume_trade t ON t.order_id = b.order_id LEFT JOIN ${database.prefix.supplier}hou_shop_base sb ON sb.supplier_shop_id = b.shop_id WHERE b.pay_code in (6,7,8)
and r.trade_type_id = #{param.tradeTypeId,jdbcType=TINYINT} and r.user_type = 2
and r.trade_type_id = #{param.tradeTypeId,jdbcType=TINYINT} and r.user_type = 1 and (b.order_return_status = 2 OR b.order_refund_status = 2)
and r.user_id = #{param.userId}
and r.record_payorder = #{param.orderId,jdbcType=VARCHAR}
and (r.record_time BETWEEN #{param.startDate} and #{param.endDate})
